 const sheetTitle=sheet?.kind==='carForm'?t(sheet.item?'editCar':'newCar'):sheet?.kind==='meetForm'?t(sheet.item?'editMeet':'newMeet'):sheet?.kind==='crewForm'?t(sheet.item?'edit':'newCrew'):sheet?.kind==='profileForm'?t('editProfile'):sheet?.kind==='crew'?t('crewNotebook'):'REVREN';
