// Native map stays in the native bundle; the web export provides map deep links.
function MeetMap({items,t,open,maps}){const [Map,setMap]=useState(null);useEffect(()=>{if(Platform.OS!=='web'){try{const m=require('react-native-maps');setMap({View:m.default,Marker:m.Marker})}catch{}}},[]);return <View>{Map&&<View style={s.mapWrap}><Map.View style={{flex:1}} initialRegion={{latitude:49.76,longitude:18.3,latitudeDelta:.6,longitudeDelta:.6}} userInterfaceStyle="dark">{items.filter(x=>Number.isFinite(x.lat)).map(x=><Map.Marker key={x.id} coordinate={{latitude:x.lat,longitude:x.lng}} title={x.title} description={x.location} pinColor={C.orange} onCalloutPress={()=>open(x)}/>)}</Map.View></View>}<Txt style={[s.disclosure,{marginBottom:16}]}>{t('mapUnavailable')}</Txt>{items.map(item=><View key={item.id} style={s.mapRow}><Tap onPress={()=>open(item)} label={item.title} style={{flex:1}}><Txt style={s.mapTitle}>{item.title}</Txt><Txt style={s.meta}>{item.location} · {item.city}</Txt></Tap><Tap label={t('directions')} onPress={()=>maps(item)} style={s.iconButton}><I name="navigation" color={C.orange}/></Tap></View>)}</View>}

